                    try writeRune(w, x.a);
                    if (x.b != 0) {
                        try w.writeByte('-');
                        try writeRune(w, x.b);
                    }
                    try w.writeByte('\'');
                    if (i + 1 < e.expected.len) try w.writeAll(", ");
                }
                try w.writeAll(" but got ");
            } else {
                try w.writeAll("Unexpected ");
            }
            if (e.unexpected) |r| {
                try w.writeByte('\'');
                try writeRune(w, r);
                try w.writeByte('\'');
            } else {
                try w.writeAll("EOF");
            }
        }

